  'reject.reason.future': "\"Du er fremtiden – vi bygger holdet om dig de kommende år\"", 'reject.r.future.2': "{player}: Wow, tak chef. Det betyder alt for mig. Jeg vil blive her og vise, at du har ret.", 'reject.r.future.1': "{player}: Det er rart at høre. Men så vil jeg også have chancen på banen.", 'reject.r.future.0': "{player}: Fremtiden? Det tror jeg ikke helt på – jeg kan se, hvem der spiller.", 'reject.r.future.1Calm': "{player}: Tak, chef. Jeg havde nu heller ikke travlt med at komme til {club}.", 'reject.r.future.0Calm': "{player}: Okay… Jeg var nu heller ikke så interesseret i {club}.",
